package com.xplayer.lite;
import android.content.*;
import android.database.Cursor;
import android.net.Uri;
import android.provider.DocumentsContract;
import java.util.*;
final class TreeScanner{
 private static final Set<String> VIDEO=new HashSet<>(Arrays.asList("mp4","mkv","avi","mov","flv","webm","wmv","mpeg","mpg","ts","m2ts","3gp","rmvb","vob","ogv","m4v","iso"));
 private static final Set<String> AUDIO=new HashSet<>(Arrays.asList("mp3","aac","ac3","eac3","dts","flac","wav","wma","ogg","opus","m4a","alac","amr","aiff","aif","ape","mka"));
 static String extension(String name){int i=name.lastIndexOf('.');return i<0?"":name.substring(i+1).toLowerCase(Locale.ROOT);}
 static int kind(String name,String mime){if(mime!=null){if(mime.startsWith("video/"))return 1;if(mime.startsWith("audio/"))return 2;}String e=extension(name);return VIDEO.contains(e)?1:AUDIO.contains(e)?2:0;}
 static boolean subtitle(String name){return Arrays.asList("srt","ass","ssa","vtt").contains(extension(name));}
 static String stem(String name){int i=name.lastIndexOf('.');return (i<0?name:name.substring(0,i)).toLowerCase(Locale.ROOT);}
 static final class Entry{Uri uri;String name,mime,id;long size,modified;boolean folder;Entry(Uri u,String n,String m,String id,long size,long modified){uri=u;name=n;mime=m;this.id=id;this.size=size;this.modified=modified;folder=DocumentsContract.Document.MIME_TYPE_DIR.equals(m);}}
 static List<Entry> children(Context c,Uri tree,String parent){ArrayList<Entry> result=new ArrayList<>();Uri uri=DocumentsContract.buildChildDocumentsUriUsingTree(tree,parent);String[] cols={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED};try(Cursor x=c.getContentResolver().query(uri,cols,null,null,null)){if(x!=null)while(x.moveToNext()&&result.size()<10000){String id=x.getString(0),name=x.getString(1);if(id!=null&&name!=null)result.add(new Entry(DocumentsContract.buildDocumentUriUsingTree(tree,id),name,x.getString(2),id,x.getLong(3),x.getLong(4)));}}catch(Exception e){android.util.Log.w("XPlayerTree","Folder unavailable",e);}return result;}
 private static final class Dir{String id,path;int depth;Dir(String i,String p,int d){id=i;path=p;depth=d;}}
 static void scan(Context c,Uri tree,List<LibraryActivity.Media> output){try{String root=DocumentsContract.getTreeDocumentId(tree);ArrayDeque<Dir> dirs=new ArrayDeque<>();HashSet<String> seen=new HashSet<>();dirs.add(new Dir(root,root+"/",0));int count=0;HashMap<String,String> subtitles=new HashMap<>();while(!dirs.isEmpty()&&count<10000&&!Thread.currentThread().isInterrupted()){Dir d=dirs.remove();if(!seen.add(d.id)||d.depth>32)continue;List<Entry> files=children(c,tree,d.id);HashMap<String,Entry> subs=new HashMap<>();for(Entry e:files)if(!e.folder&&subtitle(e.name))subs.put(stem(e.name),e);for(Entry e:files){if(++count>10000)break;if(e.folder){dirs.add(new Dir(e.id,d.path+e.name+"/",d.depth+1));continue;}int k=kind(e.name,e.mime);if(k==0)continue;String mime=e.mime;if(mime==null||mime.equals("application/octet-stream"))mime=k==1?"video/*":"audio/*";output.add(new LibraryActivity.Media(e.uri,e.name,d.path,tree.toString(),mime,0,e.size,e.modified/1000,k==1));Entry sub=subs.get(stem(e.name));if(k==1&&sub!=null)subtitles.put(e.uri.toString(),sub.uri.toString());}}android.content.SharedPreferences.Editor edit=c.getSharedPreferences("tree_subtitles",Context.MODE_PRIVATE).edit();for(Map.Entry<String,String> s:subtitles.entrySet())edit.putString(s.getKey(),s.getValue());edit.apply();}catch(Exception e){android.util.Log.w("XPlayerTree","Cannot scan",e);}}
 static Uri subtitleFor(Context c,Uri media){String s=c.getSharedPreferences("tree_subtitles",Context.MODE_PRIVATE).getString(media.toString(),null);if(s==null)return null;try{Uri u=Uri.parse(s);try(android.content.res.AssetFileDescriptor d=c.getContentResolver().openAssetFileDescriptor(u,"r")){return d==null?null:u;}}catch(Exception e){return null;}}
}
